userDefinedLinkHintCss:
div > .vimiumHintMarker {
  padding: 2px 3px;
  background-color: #f8f9fa;
  border: 1px solid #005f87;
  border-radius: 3px;
  box-shadow: 0em 0.1em 0.6em 0.1em rgba(0, 0, 0, 0.1);
  background-image: none;
}

div > .vimiumHintMarker span {
  font-size: 12px;
  font-family: MesloLGM Nerd Font;
  font-weight: bold;
  text-shadow: none;
  color: #005f87;
}

div > .vimiumHintMarker > .matchingCharacter {
  color: #c4c8cc;
}

/* VOMNIBAR */
#vomnibar {
  background-color: #ffffff;
}

#vomnibar input {
  color: #3c3836;
  font-weight: normal;
  font-size: 20px;
  font-family: MesloLGM Nerd Font;
  height: 34px;
  margin-bottom: 0;
  padding: 4px;
  background-color: #f0f0f0;
  border-radius: 3px;
  border: 1px solid #dcdcdc;
  box-shadow: #87ceeb 0px 0px 1px;
  width: 100%;
  outline: none;
  box-sizing: border-box;
}

#vomnibar .vomnibarSearchArea {
  display: block;
  padding: 10px;
  background-color: #f0f0f0;
  border-radius: 4px 4px 0 0;
  border-bottom: 1px solid #87ceeb;
}

#vomnibar ul {
  background-color: #ffffff;
  border-radius: 0 0 4px 4px;
  list-style: none;
  padding-top: 0;
  padding-bottom: 0;
  margin-block-start: 2px;
  margin-block-end: 0px;
}

#vomnibar li {
  border-bottom: 1px solid #e0e0e0;
  line-height: 1.1em;
  padding: 7px 10px;
  font-size: 16px;
  color: #222222;
  position: relative;
  display: list-item;
  margin: auto;
}

#vomnibar li .vomnibarBottomHalf {
  font-size: 15px;
  margin-top: 3px;
  padding: 2px 0;
}

#vomnibar li .vomnibarSource {
  color: #007744;
  margin-right: 4px;
}

#vomnibar li .vomnibarRelevancy {
  position: absolute;
  right: 0;
  top: 0;
  padding: 5px;
  background-color: #eeeeee;
  color: #3c3836;`
  font-family: MesloLGM Nerd Font Mono;
  width: 100px;
  overflow: hidden;
}

#vomnibar li .vomnibarUrl {
  color: #0077aa;
}

#vomnibar li .vomnibarMatch {
  font-weight: bold;
  color: #3c3836;
}

#vomnibar li.vomnibarSelected {
  background-color: #d6e2f0;
}

#vomnibar li em, #vomnibar li .vomnibarTitle {
  color: #3c3836;
  margin-left: 4px;
  font-weight: normal;
}

#vomnibar li em {
  font-style: italic;
}

#vomnibar li em .vomnibarMatch, 
#vomnibar li .vomnibarTitle .vomnibarMatch {
  color: #d65d0e;
}

#vomnibarInput::selection {
  background-color: #005f87;
}
